resource='src/Erlang.Runtime/ResourceReferenceTerm.cs';assert (C/resource).read_bytes()==(R/resource).read_bytes();supporting.append({'Path':resource,'Sha256':sha((C/resource).read_bytes()),'RawExactPublished347':True})
